CREATE OR REPLACE FUNCTION public.actualizar_estado_daily_reports()
 RETURNS void
 LANGUAGE plpgsql
AS $function$DECLARE 
    report_record RECORD; 
    row_record RECORD; 
    tiene_filas BOOLEAN; 
    todas_completas BOOLEAN; 
    tiene_recursos BOOLEAN; 
BEGIN 
    -- Primero, para todos los reportes, verificar filas con 'sin_recursos_asignados' que ahora tienen recursos 
    FOR row_record IN 
        SELECT dr.id 
        FROM dailyreportrows dr 
        WHERE dr.status = 'sin_recursos_asignados' 
    LOOP 
        -- Verificar si hay recursos asignados (empleados o equipos) 
        SELECT EXISTS ( 
            SELECT 1 FROM dailyreportemployeerelations 
            WHERE daily_report_row_id = row_record.id 
            UNION 
            SELECT 1 FROM dailyreportequipmentrelations 
            WHERE daily_report_row_id = row_record.id 
        ) INTO tiene_recursos; 
        
        -- Si tiene recursos, actualizar el estado a 'pendiente' 
        IF tiene_recursos THEN 
            UPDATE dailyreportrows 
            SET status = 'pendiente', 
                updated_at = (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires') 
            WHERE id = row_record.id; 
        END IF; 
    END LOOP; 

    -- Luego, continuar con la lógica de cierre para reportes pasados con estado 'abierto' o 'cerrado_incompleto' 
    FOR report_record IN 
        SELECT id 
        FROM dailyreport 
        WHERE date < ( (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires')::date ) 
        AND status IN ('abierto', 'cerrado_incompleto')  
    LOOP 
        -- Verificar si el reporte tiene filas asociadas 
        SELECT EXISTS (SELECT 1 FROM dailyreportrows WHERE daily_report_id = report_record.id) INTO tiene_filas; 
        
        IF NOT tiene_filas THEN 
            -- Si no tiene filas, marcarlo como cerrado_completo 
            UPDATE dailyreport 
            SET status = 'cerrado_completo', 
                updated_at = (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires') 
            WHERE id = report_record.id; 
        ELSE 
            -- Verificar si todas las filas tienen estado 'ejecutado', 'reprogramado' o 'cancelado' 
            -- Y si son 'ejecutado', deben tener document_path 
            SELECT NOT EXISTS ( 
                SELECT 1 
                FROM dailyreportrows 
                WHERE daily_report_id = report_record.id 
                AND ( 
                    status NOT IN ('ejecutado', 'reprogramado', 'cancelado') 
                    OR (status = 'ejecutado' AND (document_path IS NULL OR document_path = '')) 
                ) 
            ) INTO todas_completas; 
            
            -- Actualizar el estado según corresponda 
            IF todas_completas THEN 
                UPDATE dailyreport 
                SET status = 'cerrado_completo', 
                    updated_at = (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires') 
                WHERE id = report_record.id; 
            ELSE 
                UPDATE dailyreport 
                SET status = 'cerrado_incompleto', 
                    updated_at = (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires') 
                WHERE id = report_record.id; 
            END IF; 
        END IF; 
    END LOOP; 
END;$function$
;

CREATE OR REPLACE FUNCTION public.actualizar_estado_documentos()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Actualizar documentos de empleados
    UPDATE documents_employees
    SET state = 'vencido'
    WHERE validity::timestamptz < CURRENT_TIMESTAMP;

    -- Actualizar documentos de equipos
    UPDATE documents_equipment
    SET state = 'vencido'
    WHERE validity::timestamptz < CURRENT_TIMESTAMP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.add_new_document()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE
  company_owner_id UUID;
  vehicle_id UUID;
  employee_id UUID;
BEGIN
  IF NEW.mandatory THEN
    IF NEW.applies = 'Equipos' THEN
      IF NEW.company_id IS NULL THEN
        FOR company_owner_id IN SELECT owner_id FROM company LOOP
          FOR vehicle_id IN SELECT id FROM vehicles WHERE company_id = company_owner_id LOOP
            INSERT INTO documents_equipment (id_document_types, applies, validity, state, is_active, user_id, deny_reason, document_path)
            VALUES (NEW.id, vehicle_id, NULL, 'pendiente', TRUE, company_owner_id, NULL, NULL);
          END LOOP;
        END LOOP;
        -- Actualizar el estado de todos los vehículos
        UPDATE vehicles SET status = 'Incompleto' WHERE company_id IN (SELECT owner_id FROM company);
      ELSE
        SELECT owner_id INTO company_owner_id FROM company WHERE id = NEW.company_id;
        FOR vehicle_id IN SELECT id FROM vehicles WHERE company_id = NEW.company_id LOOP
          INSERT INTO documents_equipment (id_document_types, applies, validity, state, is_active, user_id, deny_reason, document_path)
          VALUES (NEW.id, vehicle_id, NULL, 'pendiente', TRUE, company_owner_id, NULL, NULL);
        END LOOP;
        -- Actualizar el estado de todos los vehículos
        UPDATE vehicles SET status = 'Incompleto' WHERE company_id = NEW.company_id;
      END IF;
    ELSIF NEW.applies = 'Persona' THEN
      IF NEW.company_id IS NULL THEN
        FOR company_owner_id IN SELECT owner_id FROM company LOOP
          FOR employee_id IN SELECT id FROM employees WHERE company_id = company_owner_id LOOP
            INSERT INTO documents_employees (id_document_types, applies, validity, state, is_active, user_id, deny_reason, document_path)
            VALUES (NEW.id, employee_id, NULL, 'pendiente', TRUE, company_owner_id, NULL, NULL);
          END LOOP;
        END LOOP;
        -- Actualizar el estado de todos los empleados
        UPDATE employees SET status = 'Incompleto' WHERE company_id IN (SELECT owner_id FROM company);
      ELSE
        SELECT owner_id INTO company_owner_id FROM company WHERE id = NEW.company_id;
        FOR employee_id IN SELECT id FROM employees WHERE company_id = NEW.company_id LOOP
          INSERT INTO documents_employees (id_document_types, applies, validity, state, is_active, user_id, deny_reason, document_path)
          VALUES (NEW.id, employee_id, NULL, 'pendiente', TRUE, company_owner_id, NULL, NULL);
        END LOOP;
        -- Actualizar el estado de todos los empleados
        UPDATE employees SET status = 'Incompleto' WHERE company_id = NEW.company_id;
      END IF;
    ELSIF NEW.applies = 'Empresa' THEN
      SELECT owner_id INTO company_owner_id FROM company WHERE id = NEW.company_id;
      INSERT INTO documents_company (id_document_types, applies, validity, state, is_active, user_id, deny_reason, document_path)
      VALUES (NEW.id, NEW.company_id, NULL, 'pendiente', TRUE, NULL, NULL, NULL);
    END IF;
  END IF;
  RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.add_to_companies_employees()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE
  contractor_id UUID;
BEGIN
  -- Insertar en companies_employees
  INSERT INTO companies_employees (company_id, employee_id)
  VALUES (NEW.company_id, NEW.id);

  -- Verificar si NEW.allocated_to no está vacío
  IF NEW.allocated_to IS NOT NULL AND array_length(NEW.allocated_to, 1) > 0 THEN
    -- Insertar en contractor_employee para cada ID en allocated_to
    FOREACH contractor_id IN ARRAY NEW.allocated_to
    LOOP
      INSERT INTO contractor_employee (contractor_id, employee_id)
      VALUES (contractor_id, NEW.id);
    END LOOP;
  END IF;

  RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.after_dailyreportrows_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Llamar a la función de actualización para el reporte afectado
    PERFORM actualizar_estado_daily_reports();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.after_dailyreportrows_update_specific()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_report_id uuid := NEW.daily_report_id;
    row_record RECORD;
    tiene_filas BOOLEAN;
    todas_completas BOOLEAN;
    tiene_recursos BOOLEAN;
BEGIN
    -- Primero, para el reporte afectado, verificar filas con 'sin_recursos_asignados' que ahora tienen recursos
    FOR row_record IN
        SELECT dr.id
        FROM dailyreportrows dr
        WHERE dr.status = 'sin_recursos_asignados'
          AND dr.daily_report_id = v_report_id
    LOOP
        -- Verificar si hay recursos asignados (empleados o equipos)
        SELECT EXISTS (
            SELECT 1 FROM dailyreportemployeerelations 
            WHERE daily_report_row_id = row_record.id
            UNION
            SELECT 1 FROM dailyreportequipmentrelations 
            WHERE daily_report_row_id = row_record.id
        ) INTO tiene_recursos;
        
        -- Si tiene recursos, actualizar el estado a 'pendiente'
        IF tiene_recursos THEN
            UPDATE dailyreportrows
            SET status = 'pendiente',
                updated_at = NOW()
            WHERE id = row_record.id;
        END IF;
    END LOOP;

    -- Luego, continuar con la lógica de cierre SOLO para el reporte afectado si es pasado y está abierto
    IF EXISTS (
        SELECT 1 
        FROM dailyreport 
        WHERE id = v_report_id
          AND date < CURRENT_DATE 
          AND status IN ('abierto', 'cerrado_incompleto')
    ) THEN
        -- Verificar si el reporte tiene filas asociadas
        SELECT EXISTS (SELECT 1 FROM dailyreportrows WHERE daily_report_id = v_report_id) INTO tiene_filas;
        
        IF NOT tiene_filas THEN
            -- Si no tiene filas, marcarlo como cerrado_completo
            UPDATE dailyreport 
            SET status = 'cerrado_completo', 
                updated_at = NOW() 
            WHERE id = v_report_id;
        ELSE
            -- Verificar si todas las filas tienen estado 'ejecutado', 'reprogramado' o 'cancelado'
            -- Y si son 'ejecutado', deben tener document_path
            SELECT NOT EXISTS (
                SELECT 1 
                FROM dailyreportrows 
                WHERE daily_report_id = v_report_id 
                AND (
                    -- Filas con estado no válido
                    status NOT IN ('ejecutado', 'reprogramado', 'cancelado')
                    -- O filas ejecutadas sin documento
                    OR (status = 'ejecutado' AND (document_path IS NULL OR document_path = ''))
                )
            ) INTO todas_completas;
            
            -- Actualizar el estado según corresponda
            IF todas_completas THEN
                UPDATE dailyreport 
                SET status = 'cerrado_completo', 
                    updated_at = NOW() 
                WHERE id = v_report_id;
            ELSE
                UPDATE dailyreport 
                SET status = 'cerrado_incompleto', 
                    updated_at = NOW() 
                WHERE id = v_report_id;
            END IF;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.build_employee_where(_conditions jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$DECLARE
  c       jsonb;
  parts   text[] := '{}';
  ids_txt text;
BEGIN
  IF _conditions IS NULL OR jsonb_typeof(_conditions) <> 'array' THEN
     RETURN 'TRUE';
  END IF;

  FOR c IN SELECT * FROM jsonb_array_elements(_conditions) LOOP
    SELECT '(' || string_agg(quote_literal(id), ',') || ')'
      INTO ids_txt
      FROM jsonb_array_elements_text(c -> 'ids') id;

    CASE c ->> 'relation_type'
      WHEN 'many_to_many' THEN
        parts := parts || format(
          'EXISTS (SELECT 1 FROM %I rel
                    WHERE rel.%I = employees.%I
                      AND rel.%I IN %s)',
          c ->> 'relation_table',
          c ->> 'column_on_relation',
          c ->> 'column_on_employees',
          c ->> 'filter_column',
          ids_txt
        );
      WHEN 'one_to_many' THEN
        parts := parts || format(
          'employees.%I IN %s',
          c ->> 'filter_column',
          ids_txt
        );
      ELSE
        parts := parts || format(
          'employees.%I IN %s',
          c ->> 'filter_column',
          ids_txt
        );
    END CASE;
  END LOOP;

  RETURN array_to_string(parts, ' AND ');
END;$function$
;

CREATE OR REPLACE FUNCTION public.build_employee_where_alias(_conditions jsonb, table_alias text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  c       jsonb;
  parts   text[] := '{}'::text[];
  ids_txt text;
  values_txt text;
  log_prefix text := 'build_employee_where_alias:';
BEGIN
  RAISE LOG '%s Iniciando con _conditions=%', log_prefix, _conditions;
  
  IF _conditions IS NULL OR jsonb_typeof(_conditions) <> 'array' THEN
     RAISE LOG '%s condiciones nulas o no son un array, retornando TRUE', log_prefix;
     RETURN 'TRUE';
  END IF;

  FOR c IN SELECT * FROM jsonb_array_elements(_conditions) LOOP
    RAISE LOG '%s Procesando condición: %', log_prefix, c;
    
    -- Verificar si hay IDs no vacíos disponibles
    SELECT '(' || string_agg(quote_literal(id), ',') || ')'
      INTO ids_txt
      FROM jsonb_array_elements_text(c -> 'ids') id
      WHERE id IS NOT NULL AND id <> '';
    
    RAISE LOG '%s property_key=% ids_txt=% relation_type=%', 
      log_prefix, c ->> 'property_key', ids_txt, c ->> 'relation_type';

    -- Si no hay IDs válidos, usar los valores directamente
    IF ids_txt IS NULL OR ids_txt = '()' THEN
      RAISE LOG '%s No hay IDs válidos, usando valores directamente', log_prefix;
      
      -- Obtener lista de valores como literales SQL
      SELECT '(' || string_agg(quote_literal(val), ',') || ')'
        INTO values_txt
        FROM jsonb_array_elements_text(c -> 'values') val
        WHERE val IS NOT NULL AND val <> '';
      
      RAISE LOG '%s values_txt=%', log_prefix, values_txt;
      
      -- Caso especial para contractor_employee (tabla de unión)
      IF c ->> 'property_key' = 'contractor_employee' AND c ->> 'relation_type' = 'many_to_many' THEN
        RAISE LOG '%s Usando condición especial para contractor_employee sin IDs', log_prefix;
        parts := parts || format(
          'EXISTS (
            SELECT 1 
            FROM %I rel
            JOIN customers cust ON rel.%I = cust.id
            WHERE rel.%I = %I.%I
              AND cust.name IN %s
          )',
          c ->> 'relation_table',
          c ->> 'filter_column',
          c ->> 'column_on_relation',
          table_alias,
          c ->> 'column_on_employees',
          values_txt
        );
      ELSE
        -- Para otras propiedades, omitir si no hay IDs ni una forma alternativa de filtrar
        RAISE LOG '%s No se pudo crear condición para % sin IDs válidos', log_prefix, c ->> 'property_key';
        CONTINUE;
      END IF;
    ELSE
      -- Si hay IDs válidos, usar la lógica original
      CASE c ->> 'relation_type'
        WHEN 'many_to_many' THEN
          RAISE LOG '%s Construyendo SQL para relación many_to_many', log_prefix;
          parts := parts || format(
            'EXISTS (SELECT 1 FROM %I rel
                      WHERE rel.%I = %I.%I
                        AND rel.%I IN %s)',
            c ->> 'relation_table',
            c ->> 'column_on_relation',
            table_alias,
            c ->> 'column_on_employees',
            c ->> 'filter_column',
            ids_txt
          );
          RAISE LOG '%s SQL para many_to_many: %', log_prefix, parts[array_length(parts, 1)];
        WHEN 'one_to_many' THEN
          RAISE LOG '%s Construyendo SQL para relación one_to_many', log_prefix;
          parts := parts || format(
            '%I.%I IN %s',
            table_alias,
            c ->> 'filter_column',
            ids_txt
          );
          RAISE LOG '%s SQL para one_to_many: %', log_prefix, parts[array_length(parts, 1)];
        ELSE
          RAISE LOG '%s Construyendo SQL para relación directa o desconocida', log_prefix;
          parts := parts || format(
            '%I.%I IN %s',
            table_alias,
            c ->> 'filter_column',
            ids_txt
          );
          RAISE LOG '%s SQL para relación directa: %', log_prefix, parts[array_length(parts, 1)];
      END CASE;
    END IF;
  END LOOP;

  IF array_length(parts, 1) = 0 THEN
    RAISE LOG '%s No se generaron condiciones válidas, retornando TRUE', log_prefix;
    RETURN 'TRUE';
  END IF;

  RAISE LOG '%s Finalizando, SQL construido: %', log_prefix, array_to_string(parts, ' AND ');
  RETURN array_to_string(parts, ' AND ');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.build_vehicle_where(_conditions jsonb)
