CREATE OR REPLACE FUNCTION public.log_employee_relations_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_id UUID;
    readable_data JSONB;
    employee_data RECORD;
    parent_exists BOOLEAN;
BEGIN
    -- Get the current user ID from the request context
    user_id := (current_setting('request.jwt.claims', true)::json->>'sub')::UUID;
    
    IF TG_OP = 'INSERT' THEN
        -- For INSERT, get the employee details
        SELECT e.firstname, e.lastname INTO employee_data
        FROM employees e
        WHERE e.id = NEW.employee_id;
        
        IF FOUND THEN
            readable_data := jsonb_build_object(
                'empleado_id', NEW.employee_id,
                'empleado_nombre', COALESCE(employee_data.firstname, '') || ' ' || COALESCE(employee_data.lastname, '')
            );
            
            INSERT INTO dailyreportrows_history (
                daily_report_row_id,
                related_table,
                related_id,
                action_type,
                changed_fields,
                changed_data,
                changed_by
            ) VALUES (
                NEW.daily_report_row_id,
                'dailyreportemployeerelations',
                NEW.id,
                'LINK',
                '{}'::JSONB,
                readable_data,
                user_id
            );
        END IF;
        
    ELSIF TG_OP = 'DELETE' THEN
        -- Check if parent exists first
        SELECT EXISTS (
            SELECT 1 FROM dailyreportrows WHERE id = OLD.daily_report_row_id
        ) INTO parent_exists;
        
        IF parent_exists THEN
            SELECT e.firstname, e.lastname INTO employee_data
            FROM employees e
            WHERE e.id = OLD.employee_id;
            
            IF FOUND THEN
                readable_data := jsonb_build_object(
                    'empleado_id', OLD.employee_id,
                    'empleado_nombre', COALESCE(employee_data.firstname, '') || ' ' || COALESCE(employee_data.lastname, '')
                );
                
                INSERT INTO dailyreportrows_history (
                    daily_report_row_id,
                    related_table,
                    related_id,
                    action_type,
                    changed_fields,
                    changed_data,
                    changed_by
                ) VALUES (
                    OLD.daily_report_row_id,
                    'dailyreportemployeerelations',
                    OLD.id,
                    'UNLINK',
                    '{}'::JSONB,
                    readable_data,
                    user_id
                );
            END IF;
        END IF;
    END IF;
    
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$function$
;

