CREATE OR REPLACE FUNCTION public.log_repair_changes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE
    v_count INT;
BEGIN
    -- Verificar si ya existe un registro duplicado
    SELECT COUNT(*)
    INTO v_count
    FROM repairlogs
    WHERE repair_id = NEW.id
      AND description = COALESCE(NULLIF(NEW.mechanic_description, ''), 
                CASE NEW.state
                    WHEN 'Pendiente' THEN 'La solicitud está pendiente.'
                    WHEN 'Esperando repuestos' THEN 'La solicitud está esperando repuestos.'
                    WHEN 'En reparación' THEN 'La solicitud está en reparación.'
                    WHEN 'Finalizado' THEN 'La solicitud ha sido finalizada.'
                    WHEN 'Cancelado' THEN 'La solicitud ha sido cancelada.'
                    WHEN 'Rechazado' THEN 'La solicitud ha sido rechazada.'
                    WHEN 'Programado' THEN 
                        'La solicitud ha sido programada para el ' || TO_CHAR(NEW.scheduled, 'DD') || ' de ' ||
                        CASE TO_CHAR(NEW.scheduled, 'MM')
                            WHEN '01' THEN 'enero'
                            WHEN '02' THEN 'febrero'
                            WHEN '03' THEN 'marzo'
                            WHEN '04' THEN 'abril'
                            WHEN '05' THEN 'mayo'
                            WHEN '06' THEN 'junio'
                            WHEN '07' THEN 'julio'
                            WHEN '08' THEN 'agosto'
                            WHEN '09' THEN 'septiembre'
                            WHEN '10' THEN 'octubre'
                            WHEN '11' THEN 'noviembre'
                            WHEN '12' THEN 'diciembre'
                        END
                    ELSE 'Estado desconocido.'
                END)
      AND title = NEW.state::text
      AND ABS(EXTRACT(EPOCH FROM (NEW.created_at - created_at))) < 3;

    -- Si no se encontró un duplicado, insertar el nuevo registro
    IF v_count = 0 THEN
        IF TG_OP = 'INSERT' THEN
            INSERT INTO repairlogs (modified_by_employee, modified_by_user, kilometer, repair_id, description, title)
            VALUES (NEW.employee_id, (SELECT auth.uid()), NEW.kilometer, NEW.id, 'La solicitud de mantenimiento ha sido registrada y se encuentra en estado de espera.', NEW.state::text);
        ELSIF TG_OP = 'UPDATE' THEN
            INSERT INTO repairlogs (kilometer, modified_by_user, repair_id, description, title)
            VALUES (NEW.kilometer,
                (SELECT auth.uid()),
                NEW.id, 
                COALESCE(NULLIF(NEW.mechanic_description, ''), 
                    CASE NEW.state
                        WHEN 'Pendiente' THEN 'La solicitud está pendiente.'
                        WHEN 'Esperando repuestos' THEN 'La solicitud está esperando repuestos.'
                        WHEN 'En reparación' THEN 'La solicitud está en reparación.'
                        WHEN 'Finalizado' THEN 'La solicitud ha sido finalizada.'
                        WHEN 'Cancelado' THEN 'La solicitud ha sido cancelada.'
                        WHEN 'Rechazado' THEN 'La solicitud ha sido rechazada.'
                        WHEN 'Programado' THEN 
                            'La solicitud ha sido programada para el ' || TO_CHAR(NEW.scheduled, 'DD') || ' de ' ||
                            CASE TO_CHAR(NEW.scheduled, 'MM')
                                WHEN '01' THEN 'enero'
                                WHEN '02' THEN 'febrero'
                                WHEN '03' THEN 'marzo'
                                WHEN '04' THEN 'abril'
                                WHEN '05' THEN 'mayo'
                                WHEN '06' THEN 'junio'
                                WHEN '07' THEN 'julio'
                                WHEN '08' THEN 'agosto'
                                WHEN '09' THEN 'septiembre'
                                WHEN '10' THEN 'octubre'
                                WHEN '11' THEN 'noviembre'
                                WHEN '12' THEN 'diciembre'
                            END
                        ELSE 'Estado desconocido.'
                    END
                ), 
                NEW.state::text
            );
        END IF;
    END IF;

    RETURN NEW;
END;$function$
;

CREATE OR REPLACE FUNCTION public.marcar_prepartes_vencidos()
 RETURNS void
 LANGUAGE plpgsql
AS $function$BEGIN
    UPDATE public.preparte
    SET 
        status = 'vencido',
        updated_at = NOW()
    WHERE status = 'pendiente'
    AND "executionDate" < CURRENT_DATE
    AND (
        "executionDate"::date < CURRENT_DATE
        OR 
        ("executionDate"::date = CURRENT_DATE AND "executionDate" < NOW())
    );
END;$function$
;

CREATE OR REPLACE FUNCTION public.migrate_document(target_id uuid, execute_migration boolean DEFAULT false)
 RETURNS TABLE(old_path text, new_path text, success boolean, error_message text, action_taken text, storage_migration_id uuid)
 LANGUAGE plpgsql
AS $function$
DECLARE
    doc_record RECORD;
    formatted_company_name TEXT;
    formatted_applies_name TEXT;
    formatted_document_type TEXT;
    formatted_applies_path TEXT;
    file_extension TEXT;
    version_info TEXT;
    new_storage_path TEXT;
    existing_doc RECORD;
    should_replace BOOLEAN;
    migration_id UUID;
    equipment_identifier TEXT;
BEGIN
    -- Create a temporary table to store the migration results
    CREATE TEMP TABLE IF NOT EXISTS migration_results (
        old_path TEXT,
        new_path TEXT,
        success BOOLEAN,
        error_message TEXT,
        action_taken TEXT,
        storage_migration_id UUID
    );
    
    -- Get the document and related information
    SELECT 
        d.*,
        dt.name as document_type_name,
        dt.applies as applies_type,
        c.company_name,
        c.company_cuit as company_cuit,
        v.domain as equipment_domain,
        v.serie as equipment_serie
    INTO doc_record
    FROM documents_equipment d
    JOIN document_types dt ON d.id_document_types = dt.id
    JOIN vehicles v ON d.applies::uuid = v.id
    JOIN company c ON v.company_id = c.id
    WHERE d.id = target_id;

    IF doc_record IS NULL THEN
        INSERT INTO migration_results 
        VALUES (NULL, NULL, FALSE, 'Document not found', 'SKIPPED', NULL);
        RETURN QUERY SELECT * FROM migration_results;
        DROP TABLE migration_results;
        RETURN;
    END IF;

    BEGIN
              -- Format company name (remove special chars and spaces)
        formatted_company_name := translate(LOWER(doc_record.company_name), ' áéíóúñ', '-aeioun');
        formatted_company_name := regexp_replace(formatted_company_name, '[^a-z0-9\-]', '', 'g');
        formatted_company_name := formatted_company_name || '-(' || doc_record.company_cuit || ')';
        
        -- Use domain if available, otherwise use serie, with parentheses
        equipment_identifier := COALESCE(doc_record.equipment_domain, doc_record.equipment_serie, 'sin-identificador');
        equipment_identifier := UPPER(equipment_identifier);
        equipment_identifier := equipment_identifier || '-(' || equipment_identifier || ')';
        
        -- Format document type name (replace accents, slashes and spaces with hyphens)
        formatted_document_type := translate(LOWER(doc_record.document_type_name), 'áéíóúñ', 'aeioun');
        -- Replace both spaces and slashes with hyphens
        formatted_document_type := regexp_replace(formatted_document_type, '[\s/]+', '-', 'g');
        
        -- Get file extension
        file_extension := substring(doc_record.document_path from '\.([^.]+)$');
        
        -- Determine version info based on document properties
        IF doc_record.validity IS NOT NULL THEN
            version_info := to_char(doc_record.validity::timestamp, 'DD-MM-YYYY');
        ELSIF doc_record.period IS NOT NULL THEN
            version_info := doc_record.period;
        ELSE
            version_info := 'v0';
        END IF;
        
        -- Construct new path (without adding -sp)
        new_storage_path := format('%s/equipos/%s/%s-(%s).%s',
            formatted_company_name,
            equipment_identifier,
            formatted_document_type,
            version_info,
            file_extension
        );

        -- Check for existing documents with similar path (ignoring extension)
        SELECT *
        INTO existing_doc
        FROM documents_equipment
        WHERE document_path SIMILAR TO regexp_replace(new_storage_path, '\.[^.]+$', '') || '.%'
        AND id != doc_record.id;

        should_replace := FALSE;
        
        IF existing_doc IS NOT NULL THEN
            -- Compare versions/dates to decide which to keep
            IF doc_record.validity IS NOT NULL AND existing_doc.validity IS NOT NULL THEN
                -- Keep the one with the later validity date
                should_replace := (doc_record.validity::timestamp > existing_doc.validity::timestamp);
            ELSIF doc_record.period IS NOT NULL AND existing_doc.period IS NOT NULL THEN
                -- Keep the one with the later period
                should_replace := (doc_record.period > existing_doc.period);
            ELSE
                -- If no clear versioning, keep the newer document (based on created_at)
                should_replace := (doc_record.created_at > existing_doc.created_at);
            END IF;
        END IF;

        IF execute_migration THEN
            IF existing_doc IS NULL OR should_replace THEN
                -- Registrar la migración de almacenamiento necesaria
                INSERT INTO storage_migrations (document_id, old_path, new_path)
                VALUES (doc_record.id, doc_record.document_path, new_storage_path)
                RETURNING id INTO migration_id;

                -- Update the document path in database
                UPDATE documents_equipment
                SET document_path = new_storage_path
                WHERE id = doc_record.id;

                IF existing_doc IS NOT NULL AND should_replace THEN
                    -- Mark the old document as inactive
                    UPDATE documents_equipment
                    SET is_active = FALSE
                    WHERE id = existing_doc.id;

                    -- Register the old document for deletion
                    INSERT INTO storage_migrations (document_id, old_path, new_path)
                    VALUES (existing_doc.id, existing_doc.document_path, 'TO_DELETE');
                END IF;

                INSERT INTO migration_results 
                VALUES (
                    doc_record.document_path, 
                    new_storage_path, 
                    TRUE, 
                    'Migration registered. Physical file needs to be moved.',
                    CASE 
                        WHEN existing_doc IS NOT NULL THEN 'REPLACED_EXISTING'
                        ELSE 'MIGRATED'
                    END,
                    migration_id
                );
            ELSE
                -- Keep existing document, mark current as inactive
                UPDATE documents_equipment
                SET is_active = FALSE
                WHERE id = doc_record.id;

                -- Register the current document for deletion
                INSERT INTO storage_migrations (document_id, old_path, new_path)
                VALUES (doc_record.id, doc_record.document_path, 'TO_DELETE')
                RETURNING id INTO migration_id;

                INSERT INTO migration_results 
                VALUES (
                    doc_record.document_path, 
                    existing_doc.document_path, 
                    TRUE, 
                    'Kept existing document',
                    'KEPT_EXISTING',
                    migration_id
                );
            END IF;
        ELSE
            -- Preview mode
            INSERT INTO migration_results 
            VALUES (
                doc_record.document_path, 
                new_storage_path, 
                TRUE, 
                CASE 
                    WHEN existing_doc IS NOT NULL THEN 
                        CASE 
                            WHEN should_replace THEN 'Will replace existing document'
                            ELSE 'Will keep existing document'
                        END
                    ELSE 'Will migrate'
                END,
                CASE 
                    WHEN existing_doc IS NOT NULL THEN
                        CASE 
                            WHEN should_replace THEN 'WILL_REPLACE'
                            ELSE 'WILL_KEEP_EXISTING'
                        END
                    ELSE 'WILL_MIGRATE'
                END,
                NULL
            );
        END IF;

    EXCEPTION WHEN OTHERS THEN
        -- Record error
        INSERT INTO migration_results 
        VALUES (doc_record.document_path, NULL, FALSE, SQLERRM, 'ERROR', NULL);
    END;
    
    -- Return results
    RETURN QUERY SELECT * FROM migration_results;
    
    -- Clean up
    DROP TABLE IF EXISTS migration_results;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.migrate_documents_preview()
 RETURNS TABLE(old_path text, new_path text, success boolean, error_message text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    doc_record RECORD;
    formatted_company_name TEXT;
    formatted_applies_name TEXT;
    formatted_document_type TEXT;
    formatted_applies_path TEXT;
    file_extension TEXT;
    version_info TEXT;
    new_storage_path TEXT;
BEGIN
    -- Create a temporary table to store the migration results
    CREATE TEMP TABLE IF NOT EXISTS migration_results (
        old_path TEXT,
        new_path TEXT,
        success BOOLEAN,
        error_message TEXT
    );
    
    -- Loop through all documents with old path format
    FOR doc_record IN 
        SELECT 
            d.*,
            dt.name as document_type_name,
            dt.applies as applies_type,
            c.company_name,
            c.company_cuit as company_cuit,
            CONCAT(e.firstname, ' ', e.lastname) as applies_name,
            e.cuil as applies_document
        FROM documents_employees d
        JOIN document_types dt ON d.id_document_types = dt.id
        JOIN employees e ON d.applies::uuid = e.id
        JOIN companies_employees ce ON e.id = ce.employee_id
        JOIN company c ON ce.company_id = c.id
        WHERE d.document_path LIKE 'documentos-empleados/document-%'
    LOOP
        BEGIN
            -- Format company name (remove special chars and spaces)
            formatted_company_name := translate(LOWER(doc_record.company_name), ' áéíóúñ', '-aeioun');
            formatted_company_name := regexp_replace(formatted_company_name, '[^a-z0-9\-]', '', 'g');
            formatted_company_name := formatted_company_name || '-(' || doc_record.company_cuit || ')';
            
            -- Format applies path based on document type
            formatted_applies_path := translate(LOWER(doc_record.applies_type::text), ' áéíóúñ', '-aeioun');
            formatted_applies_path := regexp_replace(formatted_applies_path, '[^a-z0-9\-]', '', 'g');
            
            -- Format applies name and document
            formatted_applies_name := translate(LOWER(doc_record.applies_name), ' áéíóúñ', '-aeioun');
            formatted_applies_name := regexp_replace(formatted_applies_name, '[^a-z0-9\-]', '', 'g');
            formatted_applies_name := formatted_applies_name || '-(' || doc_record.applies_document || ')';
            
            -- Format document type name
            formatted_document_type := translate(LOWER(doc_record.document_type_name), ' áéíóúñ', '-aeioun');
            formatted_document_type := regexp_replace(formatted_document_type, '[^a-z0-9\-]', '', 'g');
            
            -- Get file extension
            file_extension := substring(doc_record.document_path from '\.([^.]+)$');
            
            -- Determine version info based on document properties
            IF doc_record.validity IS NOT NULL THEN
                version_info := doc_record.validity;
            ELSIF doc_record.period IS NOT NULL THEN
                version_info := doc_record.period;
            ELSE
                version_info := 'v1';
            END IF;
            
            -- Construct new path
            new_storage_path := format('%s/%s/%s/%s-(%s).%s',
                formatted_company_name,
                formatted_applies_path,
                formatted_applies_name,
                formatted_document_type,
                version_info,
                file_extension
            );

            -- Store the preview
            INSERT INTO migration_results (old_path, new_path, success, error_message)
            VALUES (
                doc_record.document_path, 
                new_storage_path, 
                TRUE, 
                'PREVIEW MODE'
            );
                
        EXCEPTION WHEN OTHERS THEN
            -- Record error
            INSERT INTO migration_results (old_path, new_path, success, error_message)
            VALUES (doc_record.document_path, NULL, FALSE, SQLERRM);
        END;
    END LOOP;
    
    -- Return results
    RETURN QUERY SELECT * FROM migration_results;
    
    -- Clean up
    DROP TABLE IF EXISTS migration_results;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_document_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_company_id UUID; -- Variable para almacenar el company_id
    resource text;
BEGIN
    -- Obtener el company_id basado en el ID proporcionado
    select 
  company_id INTO v_company_id
from
  documents_employees
  inner join employees on documents_employees.applies = employees.id
where
  documents_employees.id = NEW.id;
   resource :='employee';

    IF v_company_id IS NULL THEN
            -- Si no se encontró en documents_employees, buscar en documents_equipment
            SELECT company_id INTO v_company_id
            FROM documents_equipment  inner join vehicles on documents_equipment.applies = documents_equipment.id
            WHERE documents_equipment.id = NEW.id;
            resource :='equipment';
        END IF;

    IF NEW.state = 'rechazado' THEN
        INSERT INTO notifications (title, description, category, company_id, document_id,reference)
        VALUES ('Un documento ha sido rechazado', NEW.deny_reason, 'rechazado', v_company_id, NEW.id,resource);
    ELSIF NEW.state = 'aprobado' THEN
        INSERT INTO notifications (title, description, category, company_id, document_id,reference)
        VALUES ('Un documento ha sido aprobado', '', 'aprobado', v_company_id, NEW.id,resource);
    ELSIF NEW.state = 'vencido' THEN
        INSERT INTO notifications (title, description, category, company_id, document_id,reference)
        VALUES ('Venció un documento', '', 'vencimiento', v_company_id, NEW.id,resource);
    END IF;

    RETURN NEW;
END;

$function$
;

CREATE OR REPLACE FUNCTION public.obtener_documentos_por_vencer()
 RETURNS TABLE(tipo_documento text, correo_electronico text, fecha_vencimiento date, documento_empleado text, dominio_vehiculo text)
 LANGUAGE plpgsql
AS $function$BEGIN
    RETURN QUERY (
        SELECT 
            dt.name AS tipo_documento, 
            profile.email AS correo_electronico, 
            TO_DATE(de.validity, 'DD-MM-YYYY') AS fecha_vencimiento,
            e.document_number AS documento_empleado,
            NULL AS dominio_vehiculo
        FROM 
            documents_employees de
        JOIN 
            profile ON de.user_id = profile.id
        JOIN 
            document_types dt ON de.id_document_types = dt.id
        JOIN
            employees e ON de.applies = e.id
        WHERE 
            TO_DATE(de.validity, 'DD-MM-YYYY') >= CURRENT_DATE
            AND TO_DATE(de.validity, 'DD-MM-YYYY') < DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '45 days'
        UNION ALL
        SELECT 
            dt.name AS tipo_documento, 
            profile.email AS correo_electronico, 
            TO_DATE(de.validity, 'DD-MM-YYYY') AS fecha_vencimiento,
            NULL AS documento_empleado,
            v.domain AS dominio_vehiculo
        FROM 
            documents_equipment de
        JOIN 
            profile ON de.user_id = profile.id
        JOIN 
            document_types dt ON de.id_document_types = dt.id
        LEFT JOIN
            vehicles v ON de.applies = v.id
        WHERE 
            TO_DATE(de.validity, 'DD-MM-YYYY') >= CURRENT_DATE
            AND TO_DATE(de.validity, 'DD-MM-YYYY') < DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month'
    );
END;$function$
;

CREATE OR REPLACE FUNCTION public.process_massive_diagram_creation_v2(p_employee_ids uuid[], p_work_diagram_id uuid, p_active_novelty_id uuid, p_date_from date, p_date_to date, p_conflict_resolution text)
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_work_diagram RECORD;
    v_employee_id UUID;
    v_current_date DATE;
    v_day_in_cycle INTEGER;
    v_is_active_day BOOLEAN;
    v_existing_record RECORD;
    v_result JSON;
    v_total_employees INTEGER := 0;
    v_processed_employees INTEGER := 0;
    v_total_days INTEGER := 0;
    v_processed_days INTEGER := 0;
    v_created_records INTEGER := 0;
    v_updated_records INTEGER := 0;
    v_skipped_records INTEGER := 0;
    v_errors TEXT[] := ARRAY[]::TEXT[];
    v_start_time TIMESTAMP := NOW();
    v_end_time TIMESTAMP;
    v_created_data JSON[] := ARRAY[]::JSON[];
    v_updated_data JSON[] := ARRAY[]::JSON[];
    v_novelty_info RECORD;
    v_inactive_novelty_info RECORD;
    v_employee_name TEXT;
    v_previous_novelty RECORD;
BEGIN
    -- Validar parámetros de entrada
    IF p_date_from IS NULL OR p_date_to IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Las fechas de inicio y fin son requeridas'
        );
    END IF;
    
    IF p_date_from > p_date_to THEN
        RETURN json_build_object(
            'success', false,
            'error', 'La fecha de inicio no puede ser mayor que la fecha de fin'
        );
    END IF;
    
    IF p_employee_ids IS NULL OR array_length(p_employee_ids, 1) = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Debe seleccionar al menos un empleado'
        );
    END IF;
    
    IF p_work_diagram_id IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Debe seleccionar un diagrama de trabajo'
        );
    END IF;
    
    IF p_active_novelty_id IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Debe seleccionar una novedad activa'
        );
    END IF;
    
    -- Obtener información del diagrama de trabajo
    SELECT * INTO v_work_diagram
    FROM work_diagram
    WHERE id = p_work_diagram_id AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Diagrama de trabajo no encontrado o inactivo'
        );
    END IF;
    
    -- Obtener información de la novedad activa
    SELECT name, color INTO v_novelty_info
    FROM diagram_type
    WHERE id = p_active_novelty_id AND is_active = true;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Novedad no encontrada o inactiva'
        );
    END IF;
    
    -- Obtener información de la novedad inactiva
    SELECT name, color INTO v_inactive_novelty_info
    FROM diagram_type
    WHERE id = v_work_diagram.inactive_novelty;
    
    -- Calcular totales para el reporte
    v_total_employees := array_length(p_employee_ids, 1);
    v_total_days := (p_date_to - p_date_from + 1);
    
    -- Procesar cada empleado
    FOREACH v_employee_id IN ARRAY p_employee_ids
    LOOP
        BEGIN
            v_processed_employees := v_processed_employees + 1;
            
            -- Verificar que el empleado existe y obtener su nombre
            SELECT CONCAT(firstname, ' ', lastname) INTO v_employee_name
            FROM employees 
            WHERE id = v_employee_id;
            
            IF NOT FOUND THEN
                v_errors := array_append(v_errors, 'Empleado con ID ' || v_employee_id || ' no encontrado');
                CONTINUE;
            END IF;
            
            -- Procesar cada día en el rango
            v_current_date := p_date_from;
            WHILE v_current_date <= p_date_to LOOP
                v_processed_days := v_processed_days + 1;
                
                -- Calcular día en el ciclo (reiniciando desde p_date_from)
                v_day_in_cycle := ((v_current_date - p_date_from) % (v_work_diagram.active_working_days + v_work_diagram.inactive_working_days)) + 1;
                
                -- Determinar si es día activo
                v_is_active_day := v_day_in_cycle <= v_work_diagram.active_working_days;
                
                -- Verificar si ya existe un registro para esta fecha y empleado
                SELECT * INTO v_existing_record
                FROM employees_diagram
                WHERE employee_id = v_employee_id
                AND day = EXTRACT(DAY FROM v_current_date)
                AND month = EXTRACT(MONTH FROM v_current_date)
                AND year = EXTRACT(YEAR FROM v_current_date);
                
                IF FOUND THEN
                    -- Obtener información de la novedad anterior
                    SELECT dt.name, dt.color INTO v_previous_novelty
                    FROM diagram_type dt
                    WHERE dt.id = v_existing_record.diagram_type;
                    
                    -- Manejar conflicto según la estrategia seleccionada
                    IF p_conflict_resolution = 'skip' THEN
                        v_skipped_records := v_skipped_records + 1;
                    ELSIF p_conflict_resolution = 'update' THEN
                        UPDATE employees_diagram
                        SET 
                            diagram_type = CASE 
                                WHEN v_is_active_day THEN p_active_novelty_id
                                ELSE v_work_diagram.inactive_novelty
                            END,
                            created_at = NOW()
                        WHERE employee_id = v_employee_id
                        AND day = EXTRACT(DAY FROM v_current_date)
                        AND month = EXTRACT(MONTH FROM v_current_date)
                        AND year = EXTRACT(YEAR FROM v_current_date);
                        
                        v_updated_records := v_updated_records + 1;
                        
                        -- Agregar a los datos actualizados con información de novedad anterior
                        v_updated_data := array_append(v_updated_data, json_build_object(
                            'employee_id', v_employee_id,
                            'employee_name', v_employee_name,
                            'date', v_current_date,
                            'day', EXTRACT(DAY FROM v_current_date),
                            'month', EXTRACT(MONTH FROM v_current_date),
                            'year', EXTRACT(YEAR FROM v_current_date),
                            'is_active', v_is_active_day,
                            'novelty_name', CASE 
                                WHEN v_is_active_day THEN v_novelty_info.name 
                                ELSE v_inactive_novelty_info.name 
                            END,
                            'novelty_color', CASE 
                                WHEN v_is_active_day THEN v_novelty_info.color 
                                ELSE v_inactive_novelty_info.color 
                            END,
                            'previous_novelty_name', v_previous_novelty.name,
                            'previous_novelty_color', v_previous_novelty.color
                        ));
                    END IF;
                ELSE
                    -- Crear nuevo registro para días activos e inactivos
                    INSERT INTO employees_diagram (
                        employee_id,
                        diagram_type,
                        day,
                        month,
                        year,
                        created_at
                    ) VALUES (
                        v_employee_id,
                        CASE 
                            WHEN v_is_active_day THEN p_active_novelty_id
                            ELSE v_work_diagram.inactive_novelty
                        END,
                        EXTRACT(DAY FROM v_current_date),
                        EXTRACT(MONTH FROM v_current_date),
                        EXTRACT(YEAR FROM v_current_date),
                        NOW()
                    );
                    
                    v_created_records := v_created_records + 1;
                    
                    -- Agregar a los datos creados
                    v_created_data := array_append(v_created_data, json_build_object(
                        'employee_id', v_employee_id,
                        'employee_name', v_employee_name,
                        'date', v_current_date,
                        'day', EXTRACT(DAY FROM v_current_date),
                        'month', EXTRACT(MONTH FROM v_current_date),
                        'year', EXTRACT(YEAR FROM v_current_date),
                        'is_active', v_is_active_day,
                        'novelty_name', CASE 
                            WHEN v_is_active_day THEN v_novelty_info.name 
                            ELSE v_inactive_novelty_info.name 
                        END,
                        'novelty_color', CASE 
                            WHEN v_is_active_day THEN v_novelty_info.color 
                            ELSE v_inactive_novelty_info.color 
                        END
                    ));
                END IF;
                
                v_current_date := v_current_date + 1;
            END LOOP;
            
        EXCEPTION
            WHEN OTHERS THEN
                v_errors := array_append(v_errors, 'Error procesando empleado ' || v_employee_id || ': ' || SQLERRM);
        END;
    END LOOP;
    
    v_end_time := NOW();
    
    -- Construir respuesta
    v_result := json_build_object(
        'success', true,
        'summary', json_build_object(
            'total_employees', v_total_employees,
            'processed_employees', v_processed_employees,
            'total_days', v_total_days,
            'processed_days', v_processed_days,
            'created_records', v_created_records,
            'updated_records', v_updated_records,
            'skipped_records', v_skipped_records,
            'errors_count', array_length(v_errors, 1),
            'processing_time_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
            'start_time', v_start_time,
            'end_time', v_end_time
        ),
        'data', json_build_object(
            'created', v_created_data,
            'updated', v_updated_data
        ),
        'details', json_build_object(
            'date_range', json_build_object(
                'from', p_date_from,
                'to', p_date_to
            ),
            'work_diagram', json_build_object(
                'id', v_work_diagram.id,
                'name', v_work_diagram.name,
                'active_days', v_work_diagram.active_working_days,
                'inactive_days', v_work_diagram.inactive_working_days,
                'cycle_length', v_work_diagram.active_working_days + v_work_diagram.inactive_working_days
            ),
            'active_novelty', json_build_object(
                'id', p_active_novelty_id,
                'name', v_novelty_info.name,
                'color', v_novelty_info.color
            ),
            'inactive_novelty', json_build_object(
                'id', v_work_diagram.inactive_novelty,
                'name', v_inactive_novelty_info.name,
                'color', v_inactive_novelty_info.color
            ),
            'conflict_resolution', p_conflict_resolution,
            'employee_ids', p_employee_ids
        ),
        'errors', v_errors
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error interno del servidor: ' || SQLERRM,
            'details', json_build_object(
                'processed_employees', v_processed_employees,
                'processed_days', v_processed_days,
                'created_records', v_created_records,
                'updated_records', v_updated_records,
                'skipped_records', v_skipped_records
            )
        );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.pruebaemail()
 RETURNS void
 LANGUAGE plpgsql
AS $function$DECLARE
    destinatario TEXT;
    asunto TEXT;
    contenido TEXT;
    documentos_usuario TEXT[];
    documento RECORD;
    destinatarios_adicionales TEXT[];
    todos_destinatarios TEXT[];
      nombre_compania TEXT;
BEGIN
    -- Obtener todos los destinatarios únicos
    FOR destinatario IN SELECT DISTINCT profile.email FROM profile
    LOOP
        -- Inicializar el contenido del correo electrónico para el destinatario actual
        contenido := '';

        

        -- Obtener todos los documentos para el destinatario actual
        SELECT 
            array_agg(
                E'<br>Tipo de documento: ' || tipo_documento ||
                '<br>Fecha de vencimiento: ' || fecha_vencimiento ||
                CASE WHEN documento_empleado IS NOT NULL THEN '<br>Documento del empleado: ' || documento_empleado ELSE '' END ||
                CASE WHEN dominio_vehiculo IS NOT NULL THEN '<br>Dominio del vehículo: ' || dominio_vehiculo ELSE '' END
            )
        INTO documentos_usuario
        FROM (
            SELECT 
                dt.name AS tipo_documento, 
                TO_DATE(de.validity, 'DD-MM-YYYY') AS fecha_vencimiento,
                e.document_number AS documento_empleado,
                v.domain AS dominio_vehiculo
            FROM 
                documents_employees de
            JOIN 
                profile ON de.user_id = profile.id
            JOIN 
                document_types dt ON de.id_document_types = dt.id
            LEFT JOIN
                employees e ON de.applies = e.id
            LEFT JOIN
                vehicles v ON de.applies = v.id
            WHERE 
                TO_DATE(de.validity, 'DD-MM-YYYY') >= CURRENT_DATE
                AND TO_DATE(de.validity, 'DD-MM-YYYY') < DATE_TRUNC('day', CURRENT_DATE) + INTERVAL '45 days'
                AND profile.email = destinatario
            UNION ALL
            SELECT 
                dt.name AS tipo_documento, 
                TO_DATE(de.validity, 'DD-MM-YYYY') AS fecha_vencimiento,
                NULL AS documento_empleado,
                v.domain AS dominio_vehiculo
            FROM 
                documents_equipment de
            JOIN 
                profile ON de.user_id = profile.id
            JOIN 
                document_types dt ON de.id_document_types = dt.id
            LEFT JOIN
                vehicles v ON de.applies = v.id
            WHERE 
                TO_DATE(de.validity, 'DD-MM-YYYY') >= CURRENT_DATE
                AND TO_DATE(de.validity, 'DD-MM-YYYY') < DATE_TRUNC('day', CURRENT_DATE) + INTERVAL '45 days'
                AND profile.email = destinatario
        ) AS documentos;

          SELECT c.company_name
        INTO nombre_compania
        FROM company c
        JOIN share_company_users scu ON c.id = scu.company_id
        JOIN profile p ON scu.profile_id = p.id
        WHERE p.email = destinatario;

        -- Construir el contenido del correo electrónico con el HTML proporcionado
        contenido := '
          <!DOCTYPE html PUBLIC>
<html lang="es">
   <head>
      <meta content="text/html; charset=UTF-8" />
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
      <link
         href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap"
         rel="stylesheet"
      />
      <style>
         /* Estilos para modo claro */
         body {
            background-color: #ffffff;
            color: #0f172a;
            font-family: "Poppins", sans-serif;
         }

         .bg-primary {
            background-color: #1e293b;
         }

         .bg-muted {
            background-color: #f8fafc;
         }

         .text-primary {
            color: #1e293b;
         }

         .text-muted {
            color: #6b7280;
         }

         .text-white {
            color: #f8fafc;
         }

         /* Estilos para modo oscuro */
      </style>
   </head>
   <body>
      <table
         align="center"
         width="100%"
         border="0"
         cellpadding="0"
         cellspacing="0"
         role="presentation"
         style="max-width: 680px; margin: 0 auto"
         class="bg-muted"
      >
         <tbody>
            <tr style="width: 100%">
               <td>
                  <table
                     align="center"
                     width="100%"
                     border="0"
                     cellpadding="0"
                     cellspacing="0"
                     role="presentation"
                     style="
                        border-radius: 0.5rem 0.5rem 0 0;
                        display: flex;
                        flex-direction: column;
                     "
                     class="bg-primary"
                  >
                     <tbody>
                        <tr>
                           <td>
                              <table
                                 align="center"
                                 width="100%"
                                 border="0"
                                 cellpadding="0"
                                 cellspacing="0"
                                 role="presentation"
                              >
                                 <tbody style="width: 100%">
                                    <tr style="width: 100%">
                                       <td style="padding: 20px 30px 15px">
                                          <h1
                                             style="
                                                font-size: 27px;
                                                font-weight: bold;
                                                line-height: 27px;
                                             "
                                             class="text-white"
                                          >
                                             Codecontrol.com.ar
                                          </h1>
                                          <p
                                             style="
                                                font-size: 17px;
                                                line-height: 24px;
                                                margin: 16px 0;
                                             "
                                             class="text-white"
                                          >
                                             Documentos a Vencer en los próximos
                                             45 días
                                          </p>
                                       </td>
                                       <td style="padding: 30px 10px">
                                          <img
                                             src="https://zktcbhhlcksopklpnubj.supabase.co/storage/v1/object/public/logo/24417298440.png"
                                             style="
                                                display: block;
                                                outline: none;
                                                border: none;
                                                text-decoration: none;
                                                max-width: 100%;
                                             "
                                             width="140"
                                          />
                                       </td>
                                    </tr>
                                 </tbody>
                              </table>
                           </td>
                        </tr>
                     </tbody>
                  </table>
                  <table
                     align="center"
                     width="100%"
                     border="0"
                     cellpadding="0"
                     cellspacing="0"
                     role="presentation"
                     style="padding: 30px 30px 40px 30px"
                  >
                     <tbody>
                        <tr>
                           <td>
                              <h2
                                 style="
                                    margin: 0 0 15px;
                                    font-weight: bold;
                                    font-size: 21px;
                                    line-height: 21px;
                                 "
                                 class="text-primary"
                              >
                                 Listado de Documentos de la compañia
                                 {nombre_compania}
                              </h2>
                              <hr
                                 style="
                                    width: 100%;
                                    border: none;
                                    border-top: 1px solid #e2e8f0;
                                    margin: 30px 0;
                                 "
                              />
                              <ul>
                                 {documentos_usuario}
                              </ul>
                              <hr
                                 style="
                                    width: 100%;
                                    border: none;
                                    border-top: 1px solid #e2e8f0;
                                    margin: 30px 0;
                                 "
                              />
                              <h2
                                 style="
                                    margin: 0 0 15px;
                                    font-weight: bold;
                                    font-size: 21px;
                                    line-height: 21px;
                                 "
                                 class="text-primary"
                              >
                                 Para ver los documentos diríjase a la app
                              </h2>
                              <table
                                 align="center"
                                 width="100%"
                                 border="0"
                                 cellpadding="0"
                                 cellspacing="0"
                                 role="presentation"
                                 style="margin-top: 24px; display: block"
                              >
                                 <tbody>
                                    <tr>
                                       <td>
                                          <a
                                             href="https://codecontrol.com.ar"
                                             style="
                                                text-decoration: none;
                                                font-size: 17px;
                                                line-height: 17px;
                                                padding: 13px 17px;
                                                border-radius: 0.5rem;
                                                max-width: 120px;
                                                color: #f8fafc;
                                                background-color: #1e293b;
                                             "
                                             target="_blank"
                                             >ir a codecontrol.com.ar</a
                                          >
                                       </td>
                                    </tr>
                                 </tbody>
                              </table>
                           </td>
                        </tr>
                     </tbody>
                  </table>
               </td>
            </tr>
         </tbody>
      </table>
   </body>
</html>
';

        -- Construir el asunto del correo electrónico
        asunto := 'Documentos por vencer';

         -- Obtener los destinatarios adicionales
        SELECT array_agg(p.email)
        INTO destinatarios_adicionales
        FROM share_company_users scu
        JOIN company c ON scu.company_id = c.id
        JOIN profile p ON scu.profile_id = p.id
        WHERE c.owner_id = (SELECT id FROM profile WHERE email = destinatario);

         -- Crear el array todos_destinatarios
        todos_destinatarios := ARRAY[destinatario] || destinatarios_adicionales;

        -- Enviar el correo electrónico al destinatario actual
        PERFORM net.http_post(
            url := 'https://zktcbhhlcksopklpnubj.supabase.co/functions/v1/resend',
            body := jsonb_build_object(
                'from', 'Codecontrol <team@codecontrol.com.ar>',
              'to', todos_destinatarios,
                'subject', asunto,
                'html', contenido
            )
        );
        
    END LOOP;
END;$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_indicators_for_all_companies()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  company_record RECORD;
  v_today date := (NOW() AT TIME ZONE 'America/Argentina/Buenos_Aires')::date;
BEGIN
  FOR company_record IN SELECT id FROM company LOOP
    BEGIN
      PERFORM public.get_employee_usage_indicator(
        position_uuids => NULL::uuid[],
        save_to_table => true,
        p_company_id => company_record.id
      );

      PERFORM public.get_employee_diagram_count_by_day(
        p_day => EXTRACT(DAY FROM v_today)::integer,
        p_month => EXTRACT(MONTH FROM v_today)::integer,
        p_year => EXTRACT(YEAR FROM v_today)::integer,
        p_company_position_ids => NULL,
        save_to_table => true,
        p_company_id => company_record.id
      );

      PERFORM public.get_vehicle_usage_indicator(
        p_vehicle_type_ids => ARRAY[]::uuid[],
        p_company_id => company_record.id,
        save_to_table => true
      );

      PERFORM public.get_company_counts_indicator(
        p_company_id => company_record.id,
        save_to_table => true
      );

      PERFORM public.hr_get_absenteeism_summary(
        p_company_id => company_record.id,
        p_from => v_today,
        p_to => v_today,
        save_to_table => true
      );

      PERFORM public.hr_get_absenteeism_trend(
        p_company_id => company_record.id,
        p_from => v_today,
        p_to => v_today,
        save_to_table => true
      );

      PERFORM public.hr_get_current_absent_employees(
        p_company_id => company_record.id,
        p_date => v_today,
        save_to_table => true
      );

      PERFORM public.hr_get_daily_absence_timeseries(
        p_company_id => company_record.id,
        p_from => v_today,
        p_to => v_today,
        save_to_table => true
      );

      PERFORM public.hr_get_department_absence_reasons(
        p_company_id => company_record.id,
        p_date => v_today,
        save_to_table => true
      );

      PERFORM public.hr_get_department_absence_summary(
        p_company_id => company_record.id,
        p_date => v_today,
        save_to_table => true
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error al ejecutar indicadores para company_id %: %', company_record.id, SQLERRM;
    END;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.select_distinct_values(p_table_name text, p_column_path text, p_join_mappings jsonb DEFAULT NULL::jsonb, p_multi_join_paths jsonb DEFAULT NULL::jsonb, p_filters jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(col_value text, col_count bigint)
 LANGUAGE plpgsql
AS $function$
DECLARE
    query TEXT;
    parts TEXT[];
    current_table TEXT;
    current_column TEXT;
    join_clause TEXT := '';
    where_clause TEXT := '';
    table_alias_counter INTEGER := 1;
    i INTEGER;
    target_table TEXT;
    fk_column TEXT;
    mapping_key TEXT;
    mapping_value TEXT;
    processed_mappings JSONB;
    join_info JSONB;
    joins_array_length INTEGER;
    parsed_multi_join_paths JSONB;
    parsed_filters JSONB;
    filter_key TEXT;
    filter_value TEXT;
    filter_conditions TEXT[] := ARRAY[]::TEXT[];
BEGIN
    RAISE LOG '[SELECT_DISTINCT_VALUES] === INICIO DE EJECUCIÓN ===';
    RAISE LOG '[SELECT_DISTINCT_VALUES] Parámetros de entrada:';
    RAISE LOG '[SELECT_DISTINCT_VALUES] - p_table_name: %', p_table_name;
    RAISE LOG '[SELECT_DISTINCT_VALUES] - p_column_path: %', p_column_path;
    RAISE LOG '[SELECT_DISTINCT_VALUES] - p_join_mappings: %', p_join_mappings;
    RAISE LOG '[SELECT_DISTINCT_VALUES] - p_multi_join_paths: %', p_multi_join_paths;
    RAISE LOG '[SELECT_DISTINCT_VALUES] - p_filters: %', p_filters;
    
    -- Si se proporciona multi_join_paths, usar la nueva lógica
    IF p_multi_join_paths IS NOT NULL AND p_multi_join_paths != 'null'::jsonb THEN
        RAISE LOG '[SELECT_DISTINCT_VALUES] Usando multi_join_paths';
        
        -- Parsear el JSON si viene como string
        BEGIN
            IF jsonb_typeof(p_multi_join_paths) = 'string' THEN
                parsed_multi_join_paths := (p_multi_join_paths #>> '{}')::JSONB;
                RAISE LOG '[SELECT_DISTINCT_VALUES] JSON parseado desde string: %', parsed_multi_join_paths;
            ELSE
                parsed_multi_join_paths := p_multi_join_paths;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'Error al parsear p_multi_join_paths: %. Valor recibido: %', SQLERRM, p_multi_join_paths;
        END;
        
        -- Validar que el parámetro tenga la estructura correcta
        IF NOT (parsed_multi_join_paths ? 'joins' AND parsed_multi_join_paths ? 'final_column') THEN
            RAISE EXCEPTION 'p_multi_join_paths debe contener "joins" y "final_column". Recibido: %', parsed_multi_join_paths;
        END IF;
        
        -- Obtener la longitud del array de joins de forma segura
        joins_array_length := jsonb_array_length(parsed_multi_join_paths->'joins');
        
        IF joins_array_length IS NULL OR joins_array_length = 0 THEN
            RAISE EXCEPTION 'El array "joins" en p_multi_join_paths está vacío o es NULL';
        END IF;
        
        current_table := p_table_name;
        
        -- Construir JOINs múltiples basados en el array de joins
        FOR i IN 0..joins_array_length - 1 LOOP
            join_info := parsed_multi_join_paths->'joins'->i;
            
            -- Validar que el join_info tenga todas las propiedades necesarias
            IF NOT (join_info ? 'from_table' AND join_info ? 'to_table' AND join_info ? 'from_column' AND join_info ? 'to_column') THEN
                RAISE EXCEPTION 'Cada elemento del array "joins" debe contener: from_table, to_table, from_column, to_column';
            END IF;
            
            join_clause := join_clause || format(' LEFT JOIN %I t%s ON %I.%I::TEXT = t%s.%I::TEXT',
                join_info->>'to_table', 
                table_alias_counter,
                current_table,
                join_info->>'from_column',
                table_alias_counter,
                join_info->>'to_column'
            );
            
            RAISE LOG '[SELECT_DISTINCT_VALUES] JOIN construido: %', join_clause;
            
            current_table := 't' || table_alias_counter;
            table_alias_counter := table_alias_counter + 1;
        END LOOP;
        
        -- Extraer tabla y columna final
        parts := string_to_array(parsed_multi_join_paths->>'final_column', '.');
        IF array_length(parts, 1) = 2 THEN
            current_table := 't' || (table_alias_counter - 1); -- Usar el último alias
            current_column := parts[2];
        ELSE
            current_column := parsed_multi_join_paths->>'final_column';
        END IF;
        
    ELSE
        -- Lógica existente sin cambios
        -- Convertir string JSON a JSONB si es necesario
        BEGIN
            IF p_join_mappings IS NOT NULL AND jsonb_typeof(p_join_mappings) = 'string' THEN
                processed_mappings := (p_join_mappings #>> '{}')::JSONB;
                RAISE LOG '[SELECT_DISTINCT_VALUES] Convertido string JSON interno a JSONB: %', processed_mappings;
            ELSE
                processed_mappings := p_join_mappings;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'Error al procesar p_join_mappings: %. Valor recibido: %', SQLERRM, p_join_mappings;
        END;
        
        -- Dividir el column_path en partes
        parts := string_to_array(p_column_path, '.');
        current_table := p_table_name;
        
        -- Si hay más de una parte, es una relación anidada
        IF array_length(parts, 1) > 1 THEN
            RAISE LOG '[SELECT_DISTINCT_VALUES] Partes anidadas detectadas: %', array_to_string(parts, ', ');
            RAISE LOG '[SELECT_DISTINCT_VALUES] Procesando relación anidada...';
            
            -- Procesar cada nivel de la relación
            FOR i IN 1..array_length(parts, 1)-1 LOOP
                RAISE LOG '[SELECT_DISTINCT_VALUES] Procesando nivel %: buscando tabla destino para columna %', i, parts[i];
                
                -- Buscar en los mappings
                target_table := NULL;
                fk_column := NULL;
                
                -- Iterar sobre los mappings para encontrar la relación
                IF processed_mappings IS NOT NULL THEN
                    FOR mapping_key, mapping_value IN SELECT * FROM jsonb_each_text(processed_mappings) LOOP
                        RAISE LOG '[SELECT_DISTINCT_VALUES] Evaluando mapping: % -> %', mapping_key, mapping_value;
                        
                        -- CORREGIDO: Formato correcto {"tabla_destino": "columna_fk"}
                        IF mapping_key = parts[i] THEN
                            target_table := mapping_key;
                            fk_column := mapping_value;
                            RAISE LOG '[SELECT_DISTINCT_VALUES] Formato correcto detectado: tabla_destino=%, columna_fk=%', target_table, fk_column;
                            EXIT;
                        END IF;
                        
                        -- Formato legacy: {"columna_fk": "tabla_destino"}
                        IF mapping_value = parts[i] THEN
                            target_table := mapping_value;
                            fk_column := mapping_key;
                            RAISE LOG '[SELECT_DISTINCT_VALUES] Formato legacy detectado: tabla_destino=%, columna_fk=%', target_table, fk_column;
                            RAISE WARNING '[SELECT_DISTINCT_VALUES] Usando formato legacy de join_mappings. Se recomienda usar: {"%": "%"}', parts[i], target_table;
                            EXIT;
                        END IF;
                    END LOOP;
                END IF;
                
                -- Si no se encontró mapping, buscar por foreign key
                IF target_table IS NULL THEN
                    SELECT 
                        ccu.table_name,
                        kcu.column_name
                    INTO target_table, fk_column
                    FROM information_schema.table_constraints tc
                    JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name
                    JOIN information_schema.constraint_column_usage ccu ON ccu.constraint_name = tc.constraint_name
                    WHERE tc.constraint_type = 'FOREIGN KEY'
                      AND tc.table_name = current_table
                      AND kcu.column_name = parts[i]
                    LIMIT 1;
                    
                    IF target_table IS NOT NULL THEN
                        RAISE LOG '[SELECT_DISTINCT_VALUES] Relación encontrada por FK: tabla_destino=%, columna_fk=%', target_table, fk_column;
                    END IF;
                END IF;
                
                -- Si aún no se encontró, error
                IF target_table IS NULL THEN
                    RAISE EXCEPTION 'No se encontró clave foránea para la columna % en la tabla % y no hay mapping disponible', parts[i], current_table;
                END IF;
                
                -- Validar que la tabla destino existe
                IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = target_table AND table_schema = 'public') THEN
                    RAISE EXCEPTION 'La tabla destino % no existe', target_table;
                END IF;
                
                -- Validar que la columna FK existe en la tabla actual
                IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = current_table AND column_name = fk_column AND table_schema = 'public') THEN
                    RAISE EXCEPTION 'La columna % no existe en la tabla %', fk_column, current_table;
                END IF;
                
                -- Construir el JOIN
                join_clause := join_clause || format(' LEFT JOIN %I t%s ON %I.%I::TEXT = t%s.id::TEXT',
                    target_table, table_alias_counter, current_table, fk_column, table_alias_counter);
                
                RAISE LOG '[SELECT_DISTINCT_VALUES] JOIN construido: %', join_clause;
                
                current_table := 't' || table_alias_counter;
                table_alias_counter := table_alias_counter + 1;
            END LOOP;
            
            current_column := parts[array_length(parts, 1)];
        ELSE
            current_column := p_column_path;
        END IF;
    END IF;
    
    -- Procesar filtros si se proporcionan - CORREGIDO para manejar null correctamente
    IF p_filters IS NOT NULL AND p_filters != 'null'::jsonb AND jsonb_typeof(p_filters) != 'null' THEN
        RAISE LOG '[SELECT_DISTINCT_VALUES] Procesando filtros: %', p_filters;
        
        -- Parsear el JSON si viene como string (similar a multi_join_paths)
        BEGIN
            IF jsonb_typeof(p_filters) = 'string' THEN
                parsed_filters := (p_filters #>> '{}')::JSONB;
                RAISE LOG '[SELECT_DISTINCT_VALUES] Filtros parseados desde string: %', parsed_filters;
            ELSE
                parsed_filters := p_filters;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'Error al parsear p_filters: %. Valor recibido: %', SQLERRM, p_filters;
        END;
        
        -- Verificar que parsed_filters no sea null antes de iterar
        IF parsed_filters IS NOT NULL AND jsonb_typeof(parsed_filters) = 'object' THEN
            -- Iterar sobre cada filtro
            FOR filter_key, filter_value IN SELECT * FROM jsonb_each_text(parsed_filters) LOOP
                RAISE LOG '[SELECT_DISTINCT_VALUES] Aplicando filtro: % = %', filter_key, filter_value;
                
                -- Construir condición de filtro
                IF filter_value = 'null' THEN
                    filter_conditions := array_append(filter_conditions, format('%I.%I IS NULL', p_table_name, filter_key));
                ELSIF filter_value = 'not_null' THEN
                    filter_conditions := array_append(filter_conditions, format('%I.%I IS NOT NULL', p_table_name, filter_key));
                ELSIF filter_value IN ('true', 'false') THEN
                    -- Para valores booleanos
                    filter_conditions := array_append(filter_conditions, format('%I.%I = %s', p_table_name, filter_key, filter_value));
                ELSE
                    -- Para valores de texto
                    filter_conditions := array_append(filter_conditions, format('%I.%I::TEXT = %L', p_table_name, filter_key, filter_value));
                END IF;
            END LOOP;
        END IF;
        
        -- Construir cláusula WHERE
        IF array_length(filter_conditions, 1) > 0 THEN
            where_clause := ' WHERE ' || array_to_string(filter_conditions, ' AND ');
            RAISE LOG '[SELECT_DISTINCT_VALUES] Cláusula WHERE construida: %', where_clause;
        END IF;
    ELSE
        RAISE LOG '[SELECT_DISTINCT_VALUES] No se aplicarán filtros (p_filters es null o vacío)';
    END IF;
    
    -- Construir la consulta final - MODIFICADO para incluir valores NULL y filtros
    query := format('SELECT COALESCE(%I.%I::TEXT, ''null'') as col_value, COUNT(*) as col_count FROM %I%s%s GROUP BY COALESCE(%I.%I::TEXT, ''null'') ORDER BY col_value ASC',
        current_table, current_column, p_table_name, join_clause, where_clause, current_table, current_column);
    
    RAISE LOG '[SELECT_DISTINCT_VALUES] Consulta SQL generada: %', query;
    
    -- Ejecutar la consulta
    RETURN QUERY EXECUTE query;
    
    RAISE LOG '[SELECT_DISTINCT_VALUES] === FIN DE EJECUCIÓN ===';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_reassignment_reason(reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Establece una variable de configuración local usando true para "is_local"
  -- para que persista en transacciones futuras dentro de la misma conexión
  PERFORM set_config('myapp.reassignment_reason', reason, true);
  
  -- Agregar log para verificar
  RAISE LOG 'set_reassignment_reason called with reason: %', reason;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_controlar_alertas_employees()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Nota: la variable NEW contiene la fila que se está insertando/actualizando
  PERFORM controlar_alertas_documentos();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_controlar_alertas_vehicles()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Nota: la variable NEW contiene la fila que se está insertando/actualizando
  PERFORM controlar_alertas_documentos();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_document_types_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Si es mandatorio, verificar solo para este tipo de documento
  IF NEW.mandatory THEN
    -- Ejecuta controlar_alertas_documentos solo para este tipo de documento
    PERFORM controlar_alertas_documentos(NEW.id);
    RAISE LOG 'Trigger document_types: ejecutado controlar_alertas_documentos para document_type_id=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_document_types_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Si cambió a mandatory o ya era mandatory y se cambiaron las condiciones
  IF NEW.mandatory OR (OLD.mandatory AND NEW.conditions IS DISTINCT FROM OLD.conditions) THEN
    -- Ejecuta controlar_alertas_documentos solo para este tipo de documento
    PERFORM controlar_alertas_documentos(NEW.id);
    RAISE LOG 'Trigger document_types UPDATE: ejecutado controlar_alertas_documentos para document_type_id=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_company_by_defect()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.by_defect = true THEN
        UPDATE company
        SET by_defect = false
        WHERE owner_id = NEW.owner_id AND id <> NEW.id;
    END IF;
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_employee_diagram_status(p_employee_id uuid, p_is_active boolean)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    affected_rows INTEGER;
    result JSON;
BEGIN
    -- Verificar que el empleado existe
    IF NOT EXISTS (SELECT 1 FROM employees WHERE id = p_employee_id) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Employee not found',
            'affected_rows', 0
        );
    END IF;

    -- Actualizar todos los registros de employees_diagram para el empleado
    UPDATE employees_diagram 
    SET is_active = p_is_active
    WHERE employee_id = p_employee_id;
    
    -- Obtener el número de filas afectadas
    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    
    -- Construir respuesta
    result := json_build_object(
        'success', true,
        'message', 'Employee diagram status updated successfully',
        'affected_rows', affected_rows,
        'employee_id', p_employee_id,
        'new_status', p_is_active
    );
    
    RETURN result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error updating employee diagram status: ' || SQLERRM,
            'affected_rows', 0
        );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_status_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Para documents_employees
  IF TG_TABLE_NAME = 'documents_employees' THEN
    IF NEW.state = 'vencido' THEN
      UPDATE employees
      SET status = 'Completo con doc vencida'
      WHERE id = NEW.applies;
    ELSIF (SELECT COUNT(*) FROM documents_employees WHERE applies = NEW.applies AND state != 'presentado') = 0 THEN
      UPDATE employees
      SET status = 'Completo'
      WHERE id = NEW.applies;
    ELSE
      UPDATE employees
      SET status = 'Incompleto'
      WHERE id = NEW.applies;
    END IF;
  END IF;

  -- Para documents_equipment
  IF TG_TABLE_NAME = 'documents_equipment' THEN
    IF NEW.state = 'vencido' THEN
      UPDATE vehicles
      SET status = 'Completo con doc vencida'
      WHERE id = NEW.applies;
    ELSIF (SELECT COUNT(*) FROM documents_equipment WHERE applies = NEW.applies AND state != 'presentado') = 0 THEN
      UPDATE vehicles
      SET status = 'Completo'
      WHERE id = NEW.applies;
    ELSE
      UPDATE vehicles
      SET status = 'Incompleto'
      WHERE id = NEW.applies;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.verificar_documentos_vencidos_prueba()
 RETURNS void
 LANGUAGE plpgsql
AS $function$DECLARE
    v_company_id uuid;
    resource text;
BEGIN
    -- Establecer el estilo de fecha
    SET datestyle = 'ISO, DMY';

    -- Verificar documentos vencidos en documents_employees
    UPDATE documents_employees
    SET state = 'vencido'
    WHERE validity::date < current_date;

    -- Verificar documentos vencidos en documents_equipment
    UPDATE documents_equipment
    SET state = 'vencido'
    WHERE validity::date < current_date;

    -- Buscar company_id en documents_employees
    SELECT company_id INTO v_company_id
    FROM documents_employees
    WHERE documents_employees.id = NEW.id;

    -- Si no se encontró en documents_employees, buscar en documents_equipment
    IF v_company_id IS NULL THEN
        SELECT company_id INTO v_company_id
        FROM documents_equipment
        WHERE documents_equipment.id = NEW.id;
        resource := 'equipment';
    ELSE
        resource := 'employee';
    END IF;

    -- Insertar entrada en la tabla notifications si se cambió el estado
    IF FOUND THEN
        INSERT INTO notifications (
            title,
            description,
            category,
            company_id,
            document_id,
            reference
        )
        VALUES (
            'Venció un documento',
            '',
            'vencimiento',
            v_company_id,
            NEW.id,
            resource
        );
    END IF;
END;$function$
;

